import { describe, it, expect, beforeEach, afterEach } from 'vitest';
import * as fs from 'fs';
import * as os from 'os';
import * as path from 'path';
import {
  GITHUB_LOCKFILE,
  findLockfile,
  parseGitHubLockfile
} from './github-lockfile';

// Shape written by `gh actions-lock` (github/gh-actions-lock), v0.0.2.
const SAMPLE = [
  '# This file is machine-generated by `gh actions-lock`.',
  "version: 'v0.0.2'",
  'workflows:',
  "    '.github/workflows/ci.yml':",
  "        - 'actions/checkout@v5.0.1'",
  "        - 'github/codeql-action/upload-sarif@v3'",
  'dependencies:',
  "    'actions/checkout@v5.0.1':",
  "        ref: 'v5.0.1'",
  "        commit: 'sha1-93cb6efe18208431cddfb8368fd83d5badbf9bfd'",
  '        owner_id: 44036562',
  '        repo_id: 197814629',
  "    'github/codeql-action/upload-sarif@v3':",
  "        ref: 'v3'",
  "        commit: 'sha1-aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa'",
  '        owner_id: 1',
  '        repo_id: 2',
  '        uses:',
  "            - 'actions/attest@67422f5511b7ff725f4dbd6fb9bd2cd925c65a8d'",
  "    'actions/attest@67422f5511b7ff725f4dbd6fb9bd2cd925c65a8d':",
  "        ref: 'v1.4.1'",
  "        commit: 'sha1-67422f5511b7ff725f4dbd6fb9bd2cd925c65a8d'",
  '        owner_id: 44036562',
  '        repo_id: 760701061'
].join('\n');

describe('parseGitHubLockfile', () => {
  it('maps each dependency to its locked commit, without the sha1- prefix', () => {
    expect(parseGitHubLockfile(SAMPLE)).toEqual({
      version: 1,
      actions: {
        'actions/checkout@v5.0.1': '93cb6efe18208431cddfb8368fd83d5badbf9bfd',
        'github/codeql-action/upload-sarif@v3': 'a'.repeat(40),
        'actions/attest@67422f5511b7ff725f4dbd6fb9bd2cd925c65a8d':
          '67422f5511b7ff725f4dbd6fb9bd2cd925c65a8d'
      }
    });
  });

  it('accepts v0.0.3', () => {
    const lock = parseGitHubLockfile(SAMPLE.replace('v0.0.2', 'v0.0.3'));
    expect(Object.keys(lock.actions)).toHaveLength(3);
  });

  it('rejects a version it does not understand', () => {
    expect(() =>
      parseGitHubLockfile(SAMPLE.replace('v0.0.2', 'v0.1.0'))
    ).toThrow(/Unsupported actions\.lock version "v0\.1\.0"/);
  });

  it('rejects a dependency without a sha1 commit', () => {
    expect(() =>
      parseGitHubLockfile(SAMPLE.replace('sha1-93cb6efe', 'sha256-93cb6efe'))
    ).toThrow(/actions\/checkout@v5\.0\.1/);
  });

  it('rejects a file that is not a lockfile', () => {
    expect(() => parseGitHubLockfile('just: text')).toThrow(
      /Unsupported actions\.lock version/
    );
  });
});

describe('findLockfile', () => {
  let dir: string;
  const write = (rel: string) => {
    fs.mkdirSync(path.dirname(path.join(dir, rel)), { recursive: true });
    fs.writeFileSync(path.join(dir, rel), '');
  };

  beforeEach(() => {
    dir = fs.mkdtempSync(path.join(os.tmpdir(), 'secureci-lockfind-'));
  });
  afterEach(() => fs.rmSync(dir, { recursive: true, force: true }));

  it('finds nothing in an empty repo', () => {
    expect(findLockfile(dir)).toBeUndefined();
  });

  it("uses GitHub's actions.lock when it is the only lockfile", () => {
    write(GITHUB_LOCKFILE);
    expect(findLockfile(dir)).toEqual({
      kind: 'github',
      file: path.join(dir, GITHUB_LOCKFILE)
    });
  });

  it('prefers secureci.lock when both exist', () => {
    write(GITHUB_LOCKFILE);
    write('secureci.lock');
    expect(findLockfile(dir)).toEqual({
      kind: 'secureci',
      file: path.join(dir, 'secureci.lock')
    });
  });
});
